-- 000001 core schema: desired state for teams, people, agents, identities, secrets (references
-- only), models, budgets, usage, costs, delivery, work orders, reconcile status, outbox and audit.
--
-- Conventions
--   * All objects live in schema afs.
--   * Primary keys are prefixed ULIDs generated by the application, e.g. team_01JD3...; CHECKs pin
--     the prefix so ids are self-describing in logs and CLI output.
--   * Mutable desired-state tables carry version (optimistic concurrency, bumped by trigger) and
--     generation (bumped by the application when the spec changes; the reconciler records
--     observed_generation in resource_status).
--   * No column anywhere stores a secret value. Secrets are Secrets Manager ARNs plus metadata.
--   * Money is numeric, never float. USD only.

CREATE SCHEMA IF NOT EXISTS afs;

-- ---------------------------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------------------------

CREATE FUNCTION afs.ulid_ok(id text, prefix text) RETURNS boolean
  LANGUAGE sql IMMUTABLE PARALLEL SAFE
  RETURN id ~ ('^' || prefix || '_[0-9A-HJKMNP-TV-Z]{26}$');

-- Bumps version and updated_at on every UPDATE. The API issues
-- UPDATE ... WHERE id = $1 AND version = $2 to implement If-Match.
CREATE FUNCTION afs.touch_row() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  NEW.version := OLD.version + 1;
  NEW.updated_at := now();
  RETURN NEW;
END
$$;

-- The acting principal for revisions and audit, set per transaction by the API:
--   SET LOCAL afs.actor = 'usr_01J...';
CREATE FUNCTION afs.current_actor() RETURNS text
  LANGUAGE sql STABLE
  RETURN coalesce(nullif(current_setting('afs.actor', true), ''), 'system:' || session_user);

-- ---------------------------------------------------------------------------------------------
-- Service settings
-- ---------------------------------------------------------------------------------------------

CREATE TABLE afs.service_settings (
  key         text PRIMARY KEY CHECK (key ~ '^[a-z][a-z0-9_.]{1,62}$'),
  value       jsonb NOT NULL,
  description text,
  version     bigint NOT NULL DEFAULT 1,
  updated_at  timestamptz NOT NULL DEFAULT now(),
  updated_by  text NOT NULL DEFAULT afs.current_actor()
);

-- ---------------------------------------------------------------------------------------------
-- People and access
-- ---------------------------------------------------------------------------------------------

CREATE TABLE afs.users (
  id            text PRIMARY KEY CHECK (afs.ulid_ok(id, 'usr')),
  oidc_issuer   text NOT NULL,
  oidc_subject  text NOT NULL,
  email         text NOT NULL,
  display_name  text NOT NULL,
  disabled_at   timestamptz,
  last_login_at timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       bigint NOT NULL DEFAULT 1,
  UNIQUE (oidc_issuer, oidc_subject)
);
CREATE UNIQUE INDEX users_email_lower_uq ON afs.users (lower(email));

CREATE TABLE afs.teams (
  id               text PRIMARY KEY CHECK (afs.ulid_ok(id, 'team')),
  slug             text NOT NULL UNIQUE CHECK (slug ~ '^[a-z][a-z0-9-]{1,38}[a-z0-9]$'),
  display_name     text NOT NULL CHECK (length(display_name) BETWEEN 1 AND 120),
  description      text NOT NULL DEFAULT '',
  kind             text NOT NULL DEFAULT 'persistent' CHECK (kind IN ('persistent', 'ephemeral')),
  state            text NOT NULL DEFAULT 'active'
                     CHECK (state IN ('active', 'suspended', 'deleting', 'deleted')),
  namespace        text GENERATED ALWAYS AS ('afs-t-' || slug) STORED UNIQUE,
  cluster_id       text NOT NULL DEFAULT 'default',
  cost_center      text NOT NULL,
  owner_email      text NOT NULL,
  -- Ceiling set by service admins; team-admins set budgets up to it.
  max_budget_usd   numeric(12, 2) NOT NULL DEFAULT 0 CHECK (max_budget_usd >= 0),
  -- ResourceQuota/LimitRange settings, e.g. {"cpu":"32","memory":"128Gi","pods":100}.
  quotas           jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(quotas) = 'object'),
  labels           jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(labels) = 'object'),
  expires_at       timestamptz,
  generation       bigint NOT NULL DEFAULT 1,
  version          bigint NOT NULL DEFAULT 1,
  created_at       timestamptz NOT NULL DEFAULT now(),
  created_by       text NOT NULL DEFAULT afs.current_actor(),
  updated_at       timestamptz NOT NULL DEFAULT now(),
  deleted_at       timestamptz,
  -- Ephemeral (swarm rental / CVE) teams must expire.
  CHECK (kind = 'persistent' OR expires_at IS NOT NULL),
  CHECK ((state = 'deleted') = (deleted_at IS NOT NULL))
);
CREATE INDEX teams_expiring_idx ON afs.teams (expires_at) WHERE kind = 'ephemeral' AND deleted_at IS NULL;

-- Role bindings: service_admin is global (team_id NULL); team roles are scoped to one team.
-- Subjects are a user, an IdP group (matched on the groups claim) or a team API key.
CREATE TABLE afs.api_keys (
  id           text PRIMARY KEY CHECK (afs.ulid_ok(id, 'key')),
  team_id      text NOT NULL REFERENCES afs.teams (id) ON DELETE CASCADE,
  name         text NOT NULL,
  role         text NOT NULL CHECK (role IN ('team_admin', 'team_viewer')),
  -- Displayed prefix (e.g. "afsk_3F9Q") and SHA-256 of the full key. The key itself is shown once.
  key_prefix   text NOT NULL,
  key_sha256   bytea NOT NULL UNIQUE CHECK (length(key_sha256) = 32),
  created_at   timestamptz NOT NULL DEFAULT now(),
  created_by   text NOT NULL DEFAULT afs.current_actor(),
  expires_at   timestamptz NOT NULL,
  revoked_at   timestamptz,
  last_used_at timestamptz,
  UNIQUE (team_id, name),
  CHECK (expires_at > created_at AND expires_at <= created_at + interval '90 days')
);

CREATE TABLE afs.role_bindings (
  id           text PRIMARY KEY CHECK (afs.ulid_ok(id, 'rb')),
  role         text NOT NULL CHECK (role IN ('service_admin', 'team_admin', 'team_viewer')),
  team_id      text REFERENCES afs.teams (id) ON DELETE CASCADE,
  subject_type text NOT NULL CHECK (subject_type IN ('user', 'group')),
  user_id      text REFERENCES afs.users (id) ON DELETE CASCADE,
  group_name   text,
  version      bigint NOT NULL DEFAULT 1,
  created_at   timestamptz NOT NULL DEFAULT now(),
  created_by   text NOT NULL DEFAULT afs.current_actor(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  CHECK ((role = 'service_admin') = (team_id IS NULL)),
  CHECK ((subject_type = 'user' AND user_id IS NOT NULL AND group_name IS NULL)
      OR (subject_type = 'group' AND group_name IS NOT NULL AND user_id IS NULL))
);
CREATE UNIQUE INDEX role_bindings_subject_uq
  ON afs.role_bindings (role, team_id, subject_type, user_id, group_name) NULLS NOT DISTINCT;
CREATE INDEX role_bindings_user_idx ON afs.role_bindings (user_id) WHERE user_id IS NOT NULL;
CREATE INDEX role_bindings_group_idx ON afs.role_bindings (group_name) WHERE group_name IS NOT NULL;

-- ---------------------------------------------------------------------------------------------
-- Models and pricing (service admin)
-- ---------------------------------------------------------------------------------------------

CREATE TABLE afs.models (
  id             text PRIMARY KEY,          -- Bedrock model id, e.g. anthropic.claude-...
  provider       text NOT NULL,
  display_name   text NOT NULL,
  enabled        boolean NOT NULL DEFAULT true,
  context_window integer CHECK (context_window > 0),
  version        bigint NOT NULL DEFAULT 1,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE afs.model_prices (
  model_id                 text NOT NULL REFERENCES afs.models (id) ON DELETE CASCADE,
  effective_from           timestamptz NOT NULL,
  input_usd_per_mtok       numeric(12, 6) NOT NULL CHECK (input_usd_per_mtok >= 0),
  output_usd_per_mtok      numeric(12, 6) NOT NULL CHECK (output_usd_per_mtok >= 0),
  cache_read_usd_per_mtok  numeric(12, 6) NOT NULL DEFAULT 0 CHECK (cache_read_usd_per_mtok >= 0),
  cache_write_usd_per_mtok numeric(12, 6) NOT NULL DEFAULT 0 CHECK (cache_write_usd_per_mtok >= 0),
  source                   text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'aws_price_list', 'cur_adjusted')),
  created_at               timestamptz NOT NULL DEFAULT now(),
  created_by               text NOT NULL DEFAULT afs.current_actor(),
  PRIMARY KEY (model_id, effective_from)
);

-- Models a team may use, and the per-team Bedrock application inference profile the reconciler
-- creates for each (tagged with the team id for cost allocation).
CREATE TABLE afs.team_models (
  team_id               text NOT NULL REFERENCES afs.teams (id) ON DELETE CASCADE,
  model_id              text NOT NULL REFERENCES afs.models (id),
  inference_profile_arn text,
  version               bigint NOT NULL DEFAULT 1,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (team_id, model_id)
);

-- ---------------------------------------------------------------------------------------------
-- Secrets (references only) and agent identities
-- ---------------------------------------------------------------------------------------------

CREATE TABLE afs.secrets (
  id                  text PRIMARY KEY CHECK (afs.ulid_ok(id, 'sec')),
  team_id             text NOT NULL REFERENCES afs.teams (id) ON DELETE CASCADE,
  name                text NOT NULL CHECK (name ~ '^[a-z][a-z0-9-]{0,62}$'),
  description         text NOT NULL DEFAULT '',
  secrets_manager_arn text NOT NULL UNIQUE CHECK (secrets_manager_arn LIKE 'arn:aws%:secretsmanager:%:secret:%'),
  -- managed: created through the API (value written straight to Secrets Manager);
  -- registered: an existing secret the team tagged and referenced.
  origin              text NOT NULL CHECK (origin IN ('managed', 'registered')),
  rotation_days       integer CHECK (rotation_days BETWEEN 1 AND 365),
  current_version_id  text,
  last_changed_at     timestamptz,
  version             bigint NOT NULL DEFAULT 1,
  created_at          timestamptz NOT NULL DEFAULT now(),
  created_by          text NOT NULL DEFAULT afs.current_actor(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  UNIQUE (team_id, name),
  UNIQUE (team_id, id)
);

-- ---------------------------------------------------------------------------------------------
-- Agents
-- ---------------------------------------------------------------------------------------------

CREATE TABLE afs.agents (
  id           text PRIMARY KEY CHECK (afs.ulid_ok(id, 'agt')),
  team_id      text NOT NULL REFERENCES afs.teams (id) ON DELETE CASCADE,
  name         text NOT NULL CHECK (name ~ '^[a-z][a-z0-9-]{0,38}[a-z0-9]$'),
  description  text NOT NULL DEFAULT '',
  -- Agentic Teammates runtime template and pinned image, e.g. ghcr.io/.../hermes@sha256:...
  template     text NOT NULL,
  image        text NOT NULL CHECK (image LIKE '%@sha256:%'),
  persona      text NOT NULL DEFAULT '',
  model_id     text NOT NULL REFERENCES afs.models (id),
  replicas     integer NOT NULL DEFAULT 1 CHECK (replicas BETWEEN 0 AND 50),
  resources    jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(resources) = 'object'),
  -- Non-secret environment only. Secret material is delivered through agent_secret_bindings.
  env          jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(env) = 'object'),
  state        text NOT NULL DEFAULT 'enabled' CHECK (state IN ('enabled', 'paused', 'deleting', 'deleted')),
  generation   bigint NOT NULL DEFAULT 1,
  version      bigint NOT NULL DEFAULT 1,
  created_at   timestamptz NOT NULL DEFAULT now(),
  created_by   text NOT NULL DEFAULT afs.current_actor(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  deleted_at   timestamptz,
  UNIQUE (team_id, id),
  -- The model must be enabled for the team.
  FOREIGN KEY (team_id, model_id) REFERENCES afs.team_models (team_id, model_id)
);
CREATE UNIQUE INDEX agents_team_name_uq ON afs.agents (team_id, name) WHERE deleted_at IS NULL;

CREATE TABLE afs.agent_secret_bindings (
  team_id    text NOT NULL,
  agent_id   text NOT NULL,
  secret_id  text NOT NULL,
  delivery   text NOT NULL CHECK (delivery IN ('env', 'file')),
  -- Env var name (UPPER_SNAKE) or absolute mount path.
  target     text NOT NULL CHECK (
               (delivery = 'env' AND target ~ '^[A-Z_][A-Z0-9_]{0,127}$')
            OR (delivery = 'file' AND target ~ '^/[A-Za-z0-9._/-]{1,255}$')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text NOT NULL DEFAULT afs.current_actor(),
  PRIMARY KEY (agent_id, target),
  -- Composite keys guarantee the agent and the secret belong to the same team.
  FOREIGN KEY (team_id, agent_id) REFERENCES afs.agents (team_id, id) ON DELETE CASCADE,
  FOREIGN KEY (team_id, secret_id) REFERENCES afs.secrets (team_id, id) ON DELETE RESTRICT
);

CREATE TABLE afs.agent_identities (
  id           text PRIMARY KEY CHECK (afs.ulid_ok(id, 'aid')),
  team_id      text NOT NULL REFERENCES afs.teams (id) ON DELETE CASCADE,
  agent_id     text,           -- NULL: shared by the team (e.g. the team IAM role)
  kind         text NOT NULL CHECK (kind IN ('k8s_service_account', 'aws_iam_role', 'github_app', 'external')),
  -- SA name, role ARN, GitHub App installation id, or external account id.
  external_ref text,
  -- Credential for github_app / external identities, as a secret reference.
  secret_id    text,
  status       text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'disabled', 'error')),
  version      bigint NOT NULL DEFAULT 1,
  created_at   timestamptz NOT NULL DEFAULT now(),
  created_by   text NOT NULL DEFAULT afs.current_actor(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (team_id, agent_id) REFERENCES afs.agents (team_id, id) ON DELETE CASCADE,
  FOREIGN KEY (team_id, secret_id) REFERENCES afs.secrets (team_id, id) ON DELETE RESTRICT
);
CREATE UNIQUE INDEX agent_identities_kind_uq
  ON afs.agent_identities (team_id, agent_id, kind) NULLS NOT DISTINCT;

-- ---------------------------------------------------------------------------------------------
-- Network egress allow-list (rendered into NetworkPolicy / FQDN policy)
-- ---------------------------------------------------------------------------------------------

CREATE TABLE afs.team_egress_rules (
  id         text PRIMARY KEY CHECK (afs.ulid_ok(id, 'egr')),
  team_id    text NOT NULL REFERENCES afs.teams (id) ON DELETE CASCADE,
  host       text NOT NULL CHECK (host ~ '^(\*\.)?[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$'),
  port       integer NOT NULL DEFAULT 443 CHECK (port BETWEEN 1 AND 65535),
  purpose    text NOT NULL,
  version    bigint NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text NOT NULL DEFAULT afs.current_actor(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (team_id, host, port)
);

-- ---------------------------------------------------------------------------------------------
-- Budgets, real-time spend and usage
-- ---------------------------------------------------------------------------------------------

CREATE TABLE afs.budgets (
  id          text PRIMARY KEY CHECK (afs.ulid_ok(id, 'bud')),
  team_id     text NOT NULL UNIQUE REFERENCES afs.teams (id) ON DELETE CASCADE,
  period      text NOT NULL CHECK (period IN ('monthly', 'lifetime')),
  amount_usd  numeric(12, 2) NOT NULL CHECK (amount_usd > 0),
  thresholds  smallint[] NOT NULL DEFAULT '{50,80,100}'
                CHECK (thresholds <@ ARRAY[1,5,10,20,25,30,40,50,60,70,75,80,85,90,95,100]::smallint[]),
  on_exhaust  text NOT NULL DEFAULT 'block' CHECK (on_exhaust IN ('block', 'notify')),
  starts_at   timestamptz NOT NULL DEFAULT now(),
  expires_at  timestamptz,
  version     bigint NOT NULL DEFAULT 1,
  created_at  timestamptz NOT NULL DEFAULT now(),
  created_by  text NOT NULL DEFAULT afs.current_actor(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CHECK (expires_at IS NULL OR expires_at > starts_at)
);

-- Team-admins may set budgets only up to the ceiling a service admin set on the team.
CREATE FUNCTION afs.check_budget_ceiling() RETURNS trigger
  LANGUAGE plpgsql AS $$
DECLARE
  ceiling numeric;
BEGIN
  SELECT max_budget_usd INTO ceiling FROM afs.teams WHERE id = NEW.team_id;
  IF NEW.amount_usd > ceiling THEN
    RAISE EXCEPTION 'budget % USD exceeds team ceiling % USD', NEW.amount_usd, ceiling
      USING ERRCODE = 'check_violation', CONSTRAINT = 'budgets_amount_within_ceiling';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER budgets_ceiling BEFORE INSERT OR UPDATE OF amount_usd, team_id ON afs.budgets
  FOR EACH ROW EXECUTE FUNCTION afs.check_budget_ceiling();

-- Hot path for afs-gateway. One row per budget period (period_start = first instant of the
-- month for monthly budgets, starts_at for lifetime budgets). The gateway reserves worst-case
-- cost with a conditional UPDATE and settles to actual cost after the call; see
-- afs.reserve_spend / afs.settle_spend.
CREATE TABLE afs.spend_counters (
  budget_id    text NOT NULL REFERENCES afs.budgets (id) ON DELETE CASCADE,
  period_start timestamptz NOT NULL,
  limit_usd    numeric(14, 6) NOT NULL CHECK (limit_usd > 0),
  spent_usd    numeric(14, 6) NOT NULL DEFAULT 0 CHECK (spent_usd >= 0),
  reserved_usd numeric(14, 6) NOT NULL DEFAULT 0 CHECK (reserved_usd >= 0),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (budget_id, period_start)
);

-- Atomically reserve estimated cost. Returns true if the reservation fits under the limit.
CREATE FUNCTION afs.reserve_spend(p_budget_id text, p_period_start timestamptz, p_amount numeric)
  RETURNS boolean
  LANGUAGE sql AS $$
  WITH r AS (
    UPDATE afs.spend_counters
       SET reserved_usd = reserved_usd + p_amount, updated_at = now()
     WHERE budget_id = p_budget_id AND period_start = p_period_start
       AND spent_usd + reserved_usd + p_amount <= limit_usd
    RETURNING 1)
  SELECT EXISTS (SELECT 1 FROM r);
$$;

-- Release a reservation and record actual cost. Actual may exceed the estimate only by rounding.
CREATE FUNCTION afs.settle_spend(p_budget_id text, p_period_start timestamptz, p_reserved numeric, p_actual numeric)
  RETURNS void
  LANGUAGE sql AS $$
  UPDATE afs.spend_counters
     SET reserved_usd = greatest(reserved_usd - p_reserved, 0),
         spent_usd = spent_usd + p_actual,
         updated_at = now()
   WHERE budget_id = p_budget_id AND period_start = p_period_start;
$$;

CREATE TABLE afs.budget_threshold_events (
  budget_id    text NOT NULL REFERENCES afs.budgets (id) ON DELETE CASCADE,
  period_start timestamptz NOT NULL,
  threshold    smallint NOT NULL,
  crossed_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (budget_id, period_start, threshold)
);

-- Append-only per-request ledger written by afs-gateway, partitioned by month.
-- The reconciler creates next month's partition ahead of time with afs.ensure_usage_partition.
CREATE SEQUENCE afs.usage_events_id_seq;
CREATE TABLE afs.usage_events (
  id                 bigint NOT NULL DEFAULT nextval('afs.usage_events_id_seq'),
  occurred_at        timestamptz NOT NULL,
  team_id            text NOT NULL,
  agent_id           text,
  model_id           text NOT NULL,
  request_id         text NOT NULL,
  outcome            text NOT NULL CHECK (outcome IN ('ok', 'error', 'rejected_budget', 'rejected_model')),
  input_tokens       integer NOT NULL DEFAULT 0 CHECK (input_tokens >= 0),
  output_tokens      integer NOT NULL DEFAULT 0 CHECK (output_tokens >= 0),
  cache_read_tokens  integer NOT NULL DEFAULT 0 CHECK (cache_read_tokens >= 0),
  cache_write_tokens integer NOT NULL DEFAULT 0 CHECK (cache_write_tokens >= 0),
  cost_usd           numeric(14, 6) NOT NULL DEFAULT 0 CHECK (cost_usd >= 0),
  latency_ms         integer CHECK (latency_ms >= 0),
  PRIMARY KEY (occurred_at, id)
) PARTITION BY RANGE (occurred_at);
ALTER SEQUENCE afs.usage_events_id_seq OWNED BY afs.usage_events.id;
CREATE TABLE afs.usage_events_default PARTITION OF afs.usage_events DEFAULT;
CREATE INDEX usage_events_team_time_idx ON afs.usage_events (team_id, occurred_at);

CREATE FUNCTION afs.ensure_usage_partition(p_month date) RETURNS text
  LANGUAGE plpgsql AS $$
DECLARE
  start_ts date := date_trunc('month', p_month)::date;
  name text := format('usage_events_%s', to_char(start_ts, 'YYYYMM'));
BEGIN
  IF to_regclass('afs.' || name) IS NULL THEN
    EXECUTE format('CREATE TABLE afs.%I PARTITION OF afs.usage_events FOR VALUES FROM (%L) TO (%L)',
                   name, start_ts, (start_ts + interval '1 month')::date);
  END IF;
  RETURN name;
END
$$;

-- Daily rollups. source: gateway estimate, or billed amounts from CUR.
CREATE TABLE afs.cost_daily (
  team_id       text NOT NULL REFERENCES afs.teams (id) ON DELETE CASCADE,
  day           date NOT NULL,
  source        text NOT NULL CHECK (source IN ('gateway', 'cur_bedrock', 'cur_eks', 'cur_other')),
  agent_id      text,
  model_id      text,
  input_tokens  bigint NOT NULL DEFAULT 0,
  output_tokens bigint NOT NULL DEFAULT 0,
  cost_usd      numeric(14, 6) NOT NULL CHECK (cost_usd >= 0),
  ingested_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX cost_daily_uq
  ON afs.cost_daily (team_id, day, source, agent_id, model_id) NULLS NOT DISTINCT;

CREATE TABLE afs.cost_reconciliations (
  team_id      text NOT NULL REFERENCES afs.teams (id) ON DELETE CASCADE,
  day          date NOT NULL,
  gateway_usd  numeric(14, 6) NOT NULL,
  billed_usd   numeric(14, 6) NOT NULL,
  variance_pct numeric(8, 3) GENERATED ALWAYS AS (
                 CASE WHEN billed_usd = 0 THEN NULL
                      ELSE round((gateway_usd - billed_usd) / billed_usd * 100, 3) END) STORED,
  status       text NOT NULL CHECK (status IN ('ok', 'over_threshold', 'missing_billing')),
  reconciled_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (team_id, day)
);

-- ---------------------------------------------------------------------------------------------
-- Log delivery and notifications
-- ---------------------------------------------------------------------------------------------

CREATE TABLE afs.log_destinations (
  id         text PRIMARY KEY CHECK (afs.ulid_ok(id, 'log')),
  team_id    text NOT NULL REFERENCES afs.teams (id) ON DELETE CASCADE,
  name       text NOT NULL,
  kind       text NOT NULL CHECK (kind IN ('cloudwatch', 's3', 'otlp', 'splunk_hec', 'datadog')),
  -- Non-secret settings (log group, bucket/prefix, endpoint). Tokens via secret_id.
  config     jsonb NOT NULL CHECK (jsonb_typeof(config) = 'object'),
  secret_id  text,
  enabled    boolean NOT NULL DEFAULT true,
  version    bigint NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by text NOT NULL DEFAULT afs.current_actor(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (team_id, name),
  FOREIGN KEY (team_id, secret_id) REFERENCES afs.secrets (team_id, id) ON DELETE RESTRICT
);

-- team_id NULL: a service-level channel (service admins only).
CREATE TABLE afs.notification_channels (
  id          text PRIMARY KEY CHECK (afs.ulid_ok(id, 'nch')),
  team_id     text REFERENCES afs.teams (id) ON DELETE CASCADE,
  name        text NOT NULL,
  kind        text NOT NULL CHECK (kind IN ('slack', 'email', 'webhook', 'jira', 'eventbridge')),
  config      jsonb NOT NULL CHECK (jsonb_typeof(config) = 'object'),
  secret_id   text,
  event_types text[] NOT NULL DEFAULT '{}',
  enabled     boolean NOT NULL DEFAULT true,
  version     bigint NOT NULL DEFAULT 1,
  created_at  timestamptz NOT NULL DEFAULT now(),
  created_by  text NOT NULL DEFAULT afs.current_actor(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (team_id, secret_id) REFERENCES afs.secrets (team_id, id) ON DELETE RESTRICT
);
CREATE UNIQUE INDEX notification_channels_name_uq
  ON afs.notification_channels (team_id, name) NULLS NOT DISTINCT;

-- ---------------------------------------------------------------------------------------------
-- Work orders (phase 2/3: swarm rentals, CVE remediation)
-- ---------------------------------------------------------------------------------------------

CREATE TABLE afs.work_orders (
  id           text PRIMARY KEY CHECK (afs.ulid_ok(id, 'wo')),
  team_id      text REFERENCES afs.teams (id) ON DELETE SET NULL,
  kind         text NOT NULL CHECK (kind IN ('general', 'cve_remediation')),
  external_ref text,                                   -- e.g. CVE-2026-12345
  title        text NOT NULL,
  target_repos text[] NOT NULL DEFAULT '{}',
  owning_team  text,                                   -- team to notify (may be outside AFS)
  payload      jsonb NOT NULL DEFAULT '{}',
  sla_due_at   timestamptz,
  status       text NOT NULL DEFAULT 'open'
                 CHECK (status IN ('open', 'assigned', 'in_progress', 'pr_opened', 'done', 'failed', 'cancelled')),
  results      jsonb NOT NULL DEFAULT '{}',            -- e.g. {"pullRequests":["https://..."]}
  version      bigint NOT NULL DEFAULT 1,
  created_at   timestamptz NOT NULL DEFAULT now(),
  created_by   text NOT NULL DEFAULT afs.current_actor(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  CHECK (kind <> 'cve_remediation' OR (external_ref ~ '^CVE-[0-9]{4}-[0-9]{4,}$' AND sla_due_at IS NOT NULL))
);
CREATE INDEX work_orders_open_sla_idx ON afs.work_orders (sla_due_at) WHERE status NOT IN ('done', 'failed', 'cancelled');

-- ---------------------------------------------------------------------------------------------
-- Reconcile status, outbox, revisions, audit, exports
-- ---------------------------------------------------------------------------------------------

CREATE TABLE afs.resource_status (
  resource_kind       text NOT NULL,
  resource_id         text NOT NULL,
  team_id             text REFERENCES afs.teams (id) ON DELETE CASCADE,
  observed_generation bigint NOT NULL DEFAULT 0,
  phase               text NOT NULL DEFAULT 'Pending'
                        CHECK (phase IN ('Pending', 'Reconciling', 'Ready', 'Degraded', 'Deleting', 'Failed')),
  conditions          jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(conditions) = 'array'),
  drift_detected_at   timestamptz,
  last_reconciled_at  timestamptz,
  PRIMARY KEY (resource_kind, resource_id)
);

CREATE TABLE afs.outbox_events (
  id             bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  event_type     text NOT NULL,                        -- e.g. team.created, budget.threshold_crossed
  aggregate_kind text NOT NULL,
  aggregate_id   text NOT NULL,
  team_id        text,
  payload        jsonb NOT NULL,
  created_at     timestamptz NOT NULL DEFAULT now(),
  published_at   timestamptz,
  attempts       integer NOT NULL DEFAULT 0
);
CREATE INDEX outbox_unpublished_idx ON afs.outbox_events (id) WHERE published_at IS NULL;

-- Full snapshot of each desired-state row after every change: history and "restore revision N".
CREATE TABLE afs.config_revisions (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  resource_kind text NOT NULL,
  resource_id   text NOT NULL,
  team_id       text,
  operation     text NOT NULL CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE')),
  version       bigint,
  snapshot      jsonb NOT NULL,
  changed_by    text NOT NULL,
  changed_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX config_revisions_resource_idx ON afs.config_revisions (resource_kind, resource_id, id);
CREATE INDEX config_revisions_team_idx ON afs.config_revisions (team_id, id);

-- SECURITY DEFINER: callers (afs_app) may read revisions but never write them directly.
CREATE FUNCTION afs.record_revision() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, afs AS $$
DECLARE
  rec jsonb := to_jsonb(CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END);
  rid text := coalesce(rec ->> 'id', concat_ws('/', rec ->> 'team_id', rec ->> 'model_id'));
BEGIN
  INSERT INTO afs.config_revisions (resource_kind, resource_id, team_id, operation, version, snapshot, changed_by)
  VALUES (TG_TABLE_NAME, rid,
          CASE WHEN TG_TABLE_NAME = 'teams' THEN rec ->> 'id' ELSE rec ->> 'team_id' END,
          TG_OP, (rec ->> 'version')::bigint, rec, afs.current_actor());
  RETURN NULL;
END
$$;

CREATE TABLE afs.audit_log (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  occurred_at   timestamptz NOT NULL DEFAULT now(),
  actor_type    text NOT NULL CHECK (actor_type IN ('user', 'api_key', 'system')),
  actor_id      text NOT NULL,
  action        text NOT NULL,                         -- e.g. CreateAgent, PutBudget, DriftCorrected
  outcome       text NOT NULL CHECK (outcome IN ('allowed', 'denied', 'failed')),
  resource_kind text,
  resource_id   text,
  team_id       text,
  request_id    text,
  source_ip     inet,
  user_agent    text,
  before        jsonb,
  after         jsonb
);
CREATE INDEX audit_log_team_time_idx ON afs.audit_log (team_id, occurred_at DESC);
CREATE INDEX audit_log_actor_time_idx ON afs.audit_log (actor_id, occurred_at DESC);

CREATE FUNCTION afs.audit_log_immutable() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'afs.audit_log is append-only' USING ERRCODE = 'insufficient_privilege';
END
$$;
CREATE TRIGGER audit_log_no_update BEFORE UPDATE OR DELETE ON afs.audit_log
  FOR EACH ROW EXECUTE FUNCTION afs.audit_log_immutable();
CREATE TRIGGER audit_log_no_truncate BEFORE TRUNCATE ON afs.audit_log
  FOR EACH STATEMENT EXECUTE FUNCTION afs.audit_log_immutable();

CREATE TABLE afs.export_bundles (
  id             text PRIMARY KEY CHECK (afs.ulid_ok(id, 'exp')),
  direction      text NOT NULL CHECK (direction IN ('export', 'import')),
  schema_version integer NOT NULL,
  s3_uri         text NOT NULL,
  sha256         text NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
  dry_run        boolean NOT NULL DEFAULT false,
  status         text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'succeeded', 'failed')),
  summary        jsonb NOT NULL DEFAULT '{}',
  created_at     timestamptz NOT NULL DEFAULT now(),
  created_by     text NOT NULL DEFAULT afs.current_actor(),
  finished_at    timestamptz
);

-- ---------------------------------------------------------------------------------------------
-- Triggers on desired-state tables: version bump + revision history
-- ---------------------------------------------------------------------------------------------

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'service_settings', 'users', 'teams', 'role_bindings', 'models', 'team_models', 'secrets',
    'agents', 'agent_identities', 'team_egress_rules', 'budgets', 'log_destinations',
    'notification_channels', 'work_orders']
  LOOP
    IF t <> 'service_settings' THEN
      EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON afs.%I FOR EACH ROW EXECUTE FUNCTION afs.touch_row()',
                     t || '_touch', t);
    END IF;
    IF t NOT IN ('users', 'service_settings') THEN
      EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON afs.%I FOR EACH ROW EXECUTE FUNCTION afs.record_revision()',
                     t || '_revision', t);
    END IF;
  END LOOP;
END
$$;

-- service_settings has no id/team columns in the touch shape it shares, so bump explicitly.
CREATE FUNCTION afs.touch_setting() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  NEW.version := OLD.version + 1;
  NEW.updated_at := now();
  NEW.updated_by := afs.current_actor();
  RETURN NEW;
END
$$;
CREATE TRIGGER service_settings_touch BEFORE UPDATE ON afs.service_settings
  FOR EACH ROW EXECUTE FUNCTION afs.touch_setting();
